    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_league   leagues;
      v_capacity int;
    begin
      select * into v_league from leagues where id = p_league_id for update;
      if v_league.id is null then
        raise exception 'No such league' using errcode = 'P0002';
      end if;

