    end;
    $$;

    revoke all on function drop_player(uuid, text) from public;
    grant execute on function drop_player(uuid, text) to authenticated;

    /**
     * Settles every pending claim in the league.
     *
     * Rolling priority: the best-priority manager with a live claim wins it, then
     * drops to the bottom of the order, and the next claim is judged against the
     * new order. That is why this is a loop rather than one ordered pass — a
     * single pass would let the best-priority manager sweep every player.
     *
     * A claim whose player was taken, or whose drop is no longer held, loses with
     * a reason rather than failing the whole run.
     */
    create or replace function process_waivers(p_league_id uuid)
    returns jsonb
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_claim    waiver_claims;
      v_won      int := 0;
      v_lost     int := 0;
      v_max      int;
      v_guard    int := 0;
    begin
      loop
        -- The next claim to judge: best waiver priority first, then the manager's
        -- own ordering, then the order it was placed.
        select c.* into v_claim
          from waiver_claims c
          join managers m on m.id = c.manager_id
         where c.league_id = p_league_id
           and c.status = 'pending'
         order by m.waiver_priority, c.claim_order, c.created_at
         limit 1;

        exit when v_claim.id is null;

        -- Bounded so a bug here can never spin forever against a live database.
        v_guard := v_guard + 1;
        exit when v_guard > 10000;

        begin
          perform place_player(
            p_league_id, v_claim.manager_id,
            v_claim.add_player, v_claim.drop_player, 'waiver'
          );

          update waiver_claims
             set status = 'won', settled_at = now()
           where id = v_claim.id;

          -- Winning sends this manager to the back of the queue, and everyone
          -- below them moves up one.
          select max(waiver_priority) into v_max
            from managers where league_id = p_league_id;

          update managers
             set waiver_priority = waiver_priority - 1
           where league_id = p_league_id
             and waiver_priority > (
               select waiver_priority from managers where id = v_claim.manager_id
             );

          update managers set waiver_priority = v_max where id = v_claim.manager_id;

          v_won := v_won + 1;

        exception when others then
          update waiver_claims
             set status = 'lost', reason = sqlerrm, settled_at = now()
           where id = v_claim.id;
          v_lost := v_lost + 1;
        end;
      end loop;

      return jsonb_build_object('ok', true, 'won', v_won, 'lost', v_lost);
    end;
    $$;

    revoke all on function process_waivers(uuid) from public;

    insert into schema_migrations (name) values ('0007_waivers.sql');
    raise notice 'applied %', '0007_waivers.sql';
  end if;
end
$__migration__$;


-- ======================================================================
-- 0008_schedule.sql
-- ======================================================================

do $__migration__$
begin
  if exists (select 1 from schema_migrations where name = '0008_schedule.sql') then
    raise notice 'skipping %, already applied', '0008_schedule.sql';
  else
    -- The season schedule, and the standings that come from it.
    --
    -- Matchup used to pair managers by slot order, which meant there were no real
    -- opponents and no records. This generates a round-robin, grades each week
    -- from what the starters actually scored, and freezes a week once its games
    -- are over — otherwise a lineup change in week 6 would silently rewrite the
    -- result of week 5.

    create table matchups (
      id uuid primary key default gen_random_uuid(),
      league_id uuid not null references leagues(id) on delete cascade,
      week int not null,
      home_manager uuid references managers(id) on delete cascade,
      away_manager uuid references managers(id) on delete cascade,
      home_points numeric not null default 0,
      away_points numeric not null default 0,
      -- Who started, as they stood when the week was graded. Without this a later
      -- lineup change would make a finished week unexplainable.
      home_starters jsonb not null default '[]'::jsonb,
      away_starters jsonb not null default '[]'::jsonb,
      winner uuid references managers(id) on delete set null,
      is_tie boolean not null default false,
      final boolean not null default false,
      playoff boolean not null default false,
      graded_at timestamptz,
      unique (league_id, week, home_manager)
    );

    create index matchups_week_idx on matchups (league_id, week);

    alter table matchups enable row level security;

    create policy matchups_read on matchups
      for select using (league_id = (select league_id from current_manager()));

    /**
     * Builds the regular season as a round robin.
     *
     * The circle method: one franchise is held still and the rest rotate around
     * it, so every manager meets every other before anyone is met twice. An odd
     * league pads with a phantom, and whoever draws it has a bye that week.
     *
     * Home and away alternate by week so the same pairing is not always the same
     * way round when the schedule wraps.
     *
     * Refuses once any week has been graded final — regenerating then would throw
     * away results that already stand.
     */
    create or replace function generate_schedule(p_league_id uuid)
    returns jsonb
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_league  leagues;
      v_ids     uuid[];
      v_n       int;
      v_weeks   int;
      v_week    int;
      v_i       int;
      v_home    uuid;
      v_away    uuid;
      v_rot     uuid[];
      v_made    int := 0;
      v_byes    int := 0;
    begin
      select * into v_league from leagues where id = p_league_id for update;
      if v_league.id is null then
        raise exception 'No such league' using errcode = 'P0002';
      end if;

      if exists (select 1 from matchups where league_id = p_league_id and final) then
        raise exception 'Weeks have already been played — the schedule is fixed now'
          using errcode = '55000';
      end if;

      select array_agg(id order by slot) into v_ids
        from managers where league_id = p_league_id;

      v_n := coalesce(array_length(v_ids, 1), 0);
      if v_n < 2 then
        raise exception 'A schedule needs at least two franchises' using errcode = '55000';
      end if;

      -- An odd league gets a phantom opponent; drawing it is a bye.
      if v_n % 2 = 1 then
        v_ids := v_ids || null::uuid;
        v_n := v_n + 1;
      end if;

      v_weeks := coalesce((v_league.settings ->> 'regularWeeks')::int, 13);

      delete from matchups where league_id = p_league_id and not final;

      v_rot := v_ids;

      for v_week in 1..v_weeks loop
        for v_i in 1..(v_n / 2) loop
          -- Alternate which side is home as the weeks go by.
          if v_week % 2 = 1 then
            v_home := v_rot[v_i];
            v_away := v_rot[v_n + 1 - v_i];
          else
            v_home := v_rot[v_n + 1 - v_i];
            v_away := v_rot[v_i];
          end if;

          if v_home is null or v_away is null then
            v_byes := v_byes + 1;
            continue;
          end if;

          insert into matchups (league_id, week, home_manager, away_manager)
          values (p_league_id, v_week, v_home, v_away);
          v_made := v_made + 1;
        end loop;

        -- Rotate every position but the first.
        v_rot := array[v_rot[1]] || v_rot[v_n] || v_rot[2:v_n - 1];
      end loop;

      return jsonb_build_object('ok', true, 'weeks', v_weeks, 'matchups', v_made, 'byes', v_byes);
    end;
    $$;

    revoke all on function generate_schedule(uuid) from public;

    /** The commissioner's way in. */
    create or replace function commissioner_generate_schedule(p_league_id uuid)
    returns jsonb
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_me managers;
    begin
      select * into v_me from managers where auth_user_id = auth.uid();
      if v_me.id is null or not v_me.is_commissioner or v_me.league_id <> p_league_id then
        raise exception 'Only the commissioner can build the schedule' using errcode = '42501';
      end if;

      return generate_schedule(p_league_id);
    end;
    $$;

    revoke all on function commissioner_generate_schedule(uuid) from public;
    grant execute on function commissioner_generate_schedule(uuid) to authenticated;

    /** What a manager's starters scored in a week. */
    create or replace function lineup_points(p_league_id uuid, p_manager_id uuid, p_week int)
    returns numeric
    language sql
    stable
    as $$
      select coalesce(sum(s.points), 0)
        from roster_slots r
        join player_scores s
          on s.league_id = r.league_id
         and s.player_name = r.player_name
         and s.week = p_week
       where r.league_id = p_league_id
         and r.manager_id = p_manager_id
         and r.lineup_slot not in ('BENCH', 'IR');
    $$;

    /**
     * Scores a week and, once its games are over, freezes the result.
     *
     * A week stays open while games are still to be played, so live scores move
     * during the day. It goes final only when every game that week is complete,
     * and a final week is never regraded — a manager changing their lineup in a
     * later week must not rewrite a result that already stands.
     */
    create or replace function grade_week(p_league_id uuid, p_week int)
    returns jsonb
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_m        matchups;
      v_complete boolean;
      v_graded   int := 0;
      v_home     numeric;
      v_away     numeric;
    begin
      -- A week with no games mirrored yet cannot be closed.
      select count(*) > 0 and bool_and(completed)
        into v_complete
        from nfl_games where week = p_week;

      for v_m in
        select * from matchups
         where league_id = p_league_id and week = p_week and not final
      loop
        v_home := lineup_points(p_league_id, v_m.home_manager, p_week);
        v_away := lineup_points(p_league_id, v_m.away_manager, p_week);

        update matchups
           set home_points = v_home,
               away_points = v_away,
               home_starters = (
                 select coalesce(jsonb_agg(jsonb_build_object('name', player_name, 'slot', lineup_slot)), '[]'::jsonb)
                   from roster_slots
                  where manager_id = v_m.home_manager and lineup_slot not in ('BENCH', 'IR')
               ),
               away_starters = (
                 select coalesce(jsonb_agg(jsonb_build_object('name', player_name, 'slot', lineup_slot)), '[]'::jsonb)
                   from roster_slots
                  where manager_id = v_m.away_manager and lineup_slot not in ('BENCH', 'IR')
               ),
               winner = case
                 when not coalesce(v_complete, false) then null
                 when v_home > v_away then v_m.home_manager
                 when v_away > v_home then v_m.away_manager
                 else null
               end,
               is_tie = coalesce(v_complete, false) and v_home = v_away,
               final = coalesce(v_complete, false),
               graded_at = now()
         where id = v_m.id;

        v_graded := v_graded + 1;
      end loop;

      return jsonb_build_object('ok', true, 'week', p_week, 'graded', v_graded, 'final', coalesce(v_complete, false));
    end;
    $$;

    revoke all on function grade_week(uuid, int) from public;

    /**
     * The table. Only final weeks count toward a record — a week still being
     * played shows in the live matchup, not in the standings.
     */
    create or replace function standings(p_league_id uuid)
    returns table (
      manager_id uuid,
      slot text,
      franchise text,
      wins int,
      losses int,
      ties int,
      points_for numeric,
      points_against numeric
    )
    language sql
    stable
    as $$
      with sides as (
        select home_manager as manager_id, home_points as pf, away_points as pa,
               winner, is_tie, final
          from matchups where league_id = p_league_id
        union all
        select away_manager, away_points, home_points, winner, is_tie, final
          from matchups where league_id = p_league_id
      )
      select m.id,
             m.slot,
             m.franchise,
             count(*) filter (where s.final and s.winner = m.id)::int,
             count(*) filter (where s.final and s.winner is not null and s.winner <> m.id)::int,
             count(*) filter (where s.final and s.is_tie)::int,
             coalesce(sum(s.pf) filter (where s.final), 0),
             coalesce(sum(s.pa) filter (where s.final), 0)
        from managers m
        left join sides s on s.manager_id = m.id
       where m.league_id = p_league_id
       group by m.id, m.slot, m.franchise
       order by 4 desc, 7 desc;
    $$;

    insert into schema_migrations (name) values ('0008_schedule.sql');
    raise notice 'applied %', '0008_schedule.sql';
  end if;
end
$__migration__$;


-- ======================================================================
-- 0009_divisions.sql
-- ======================================================================

do $__migration__$
begin
  if exists (select 1 from schema_migrations where name = '0009_divisions.sql') then
    raise notice 'skipping %, already applied', '0009_divisions.sql';
  else
    -- Two divisions, with divisional rivals met twice.
    --
    -- The season is built in two phases:
    --   1. A full round robin — everyone plays everyone once.       (n-1 weeks)
    --   2. A round robin inside each division, both running at the
    --      same time, giving every divisional rival a second game.  (n/2-1 weeks)
    --
    -- So the shape of the league decides the length of the season, not the other
    -- way round: twelve franchises means sixteen regular weeks. generate_schedule
    -- writes that length back onto the league so playoffs and the rest of the app
    -- agree with the schedule that actually exists.

    alter table managers
      add column if not exists division text;

    -- Split by slot for a league that has none, so divisions are defined from the
    -- first schedule rather than being null.
    update managers m
       set division = case when seq.rn * 2 <= seq.total then 'East' else 'West' end
      from (
        select id,
               row_number() over (partition by league_id order by slot) as rn,
               count(*) over (partition by league_id) as total
          from managers
      ) seq
     where seq.id = m.id and m.division is null;

    alter table matchups
      add column if not exists divisional boolean not null default false;

    /**
     * One round robin, by the circle method: the first entry is held still and the
     * rest rotate around it, so everyone meets everyone before anyone repeats. An
     * odd list is padded, and a pairing against the padding is a bye — returned as
     * no row rather than a broken fixture.
     *
     * Home and away alternate by round so a pairing is not always the same way
     * round when this is used twice.
     */
    create or replace function round_robin(p_ids uuid[])
    returns table (rnd int, home uuid, away uuid)
    language plpgsql
    immutable
    as $$
    declare
      v_ids uuid[] := p_ids;
      v_n   int;
      v_r   int;
      v_i   int;
      v_h   uuid;
      v_a   uuid;
    begin
      v_n := coalesce(array_length(v_ids, 1), 0);
      if v_n < 2 then return; end if;

      if v_n % 2 = 1 then
        v_ids := v_ids || null::uuid;
        v_n := v_n + 1;
      end if;

      for v_r in 1..(v_n - 1) loop
        for v_i in 1..(v_n / 2) loop
          if v_r % 2 = 1 then
            v_h := v_ids[v_i];
            v_a := v_ids[v_n + 1 - v_i];
          else
            v_h := v_ids[v_n + 1 - v_i];
            v_a := v_ids[v_i];
          end if;

          if v_h is not null and v_a is not null then
            rnd := v_r; home := v_h; away := v_a;
            return next;
          end if;
        end loop;

        -- Rotate everything but the first position.
        v_ids := array[v_ids[1]] || v_ids[v_n] || v_ids[2:v_n - 1];
      end loop;
    end;
    $$;

    create or replace function generate_schedule(p_league_id uuid)
    returns jsonb
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_league    leagues;
      v_all       uuid[];
      v_divs      text[];
      v_div       text;
      v_ids       uuid[];
      v_n         int;
      v_phase1    int := 0;
      v_phase2    int := 0;
      v_rows      record;
      v_made      int := 0;
      v_byes      int := 0;
      v_divisional int := 0;
    begin
      select * into v_league from leagues where id = p_league_id for update;
      if v_league.id is null then
        raise exception 'No such league' using errcode = 'P0002';
      end if;

      if exists (select 1 from matchups where league_id = p_league_id and final) then
        raise exception 'Weeks have already been played — the schedule is fixed now'
          using errcode = '55000';
      end if;

      select array_agg(id order by slot) into v_all
        from managers where league_id = p_league_id;

      v_n := coalesce(array_length(v_all, 1), 0);
      if v_n < 2 then
        raise exception 'A schedule needs at least two franchises' using errcode = '55000';
      end if;

      delete from matchups where league_id = p_league_id and not final;

      -- Phase one: everyone plays everyone once.
      for v_rows in select * from round_robin(v_all) loop
        insert into matchups (league_id, week, home_manager, away_manager, divisional)
        values (
          p_league_id, v_rows.rnd, v_rows.home, v_rows.away,
          (select m1.division from managers m1 where m1.id = v_rows.home)
            is not distinct from
          (select m2.division from managers m2 where m2.id = v_rows.away)
        );
        v_made := v_made + 1;
        v_phase1 := greatest(v_phase1, v_rows.rnd);
      end loop;

      -- A padded round robin has as many rounds as the padded size minus one, so
      -- an odd league still spans that many weeks even where a row is a bye.
      v_phase1 := case when v_n % 2 = 1 then v_n else v_n - 1 end;

      -- Phase two: the divisional rematches. Both divisions run at the same time,
      -- because they share no franchises.
      select array_agg(distinct division order by division) into v_divs
        from managers where league_id = p_league_id and division is not null;

      if v_divs is not null then
        foreach v_div in array v_divs loop
          select array_agg(id order by slot) into v_ids
            from managers where league_id = p_league_id and division = v_div;

          for v_rows in select * from round_robin(v_ids) loop
            insert into matchups (league_id, week, home_manager, away_manager, divisional)
            values (p_league_id, v_phase1 + v_rows.rnd, v_rows.home, v_rows.away, true);
            v_made := v_made + 1;
            v_phase2 := greatest(v_phase2, v_rows.rnd);
          end loop;
        end loop;
      end if;

      select count(*) into v_divisional
        from matchups where league_id = p_league_id and divisional;

      -- Somebody sits out any week where the pairing fell against the padding.
      select (v_phase1 + v_phase2) * (v_n / 2) - v_made into v_byes;

      -- The schedule decides the season length, so the setting follows it rather
      -- than silently disagreeing with the fixtures that exist.
      update leagues
         set settings = jsonb_set(
               coalesce(settings, '{}'::jsonb),
               '{regularWeeks}',
               to_jsonb(v_phase1 + v_phase2)
             )
       where id = p_league_id;

      return jsonb_build_object(
        'ok', true,
        'weeks', v_phase1 + v_phase2,
        'matchups', v_made,
        'divisional', v_divisional,
        'byes', greatest(v_byes, 0)
      );
    end;
    $$;

    revoke all on function generate_schedule(uuid) from public;

    /** Moves a franchise to a division. Refused once a week has been played. */
    create or replace function set_division(p_manager_id uuid, p_division text)
    returns jsonb
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_me managers;
    begin
      select * into v_me from managers where auth_user_id = auth.uid();
      if v_me.id is null or not v_me.is_commissioner then
        raise exception 'Only the commissioner can set divisions' using errcode = '42501';
      end if;

      if exists (select 1 from matchups where league_id = v_me.league_id and final) then
        raise exception 'Weeks have already been played — divisions are fixed now'
          using errcode = '55000';
      end if;

      update managers set division = p_division
       where id = p_manager_id and league_id = v_me.league_id;

      if not found then
        raise exception 'No such manager in your league' using errcode = 'P0002';
      end if;

      insert into admin_log (league_id, actor, action, detail)
      values (v_me.league_id, v_me.id, 'division',
              jsonb_build_object('manager_id', p_manager_id, 'division', p_division));

      return jsonb_build_object('ok', true);
    end;
    $$;

    revoke all on function set_division(uuid, text) from public;
    grant execute on function set_division(uuid, text) to authenticated;

    /** Standings, now carrying the division and the record inside it. */
    -- The shape of the result changes, so the old one is dropped first.
    drop function if exists standings(uuid);

    create or replace function standings(p_league_id uuid)
    returns table (
      manager_id uuid,
      slot text,
      franchise text,
      division text,
      wins int,
      losses int,
      ties int,
      div_wins int,
      div_losses int,
      points_for numeric,
      points_against numeric
    )
    language sql
    stable
    as $$
      with sides as (
        select home_manager as manager_id, home_points as pf, away_points as pa,
               winner, is_tie, final, divisional
          from matchups where league_id = p_league_id
        union all
        select away_manager, away_points, home_points, winner, is_tie, final, divisional
          from matchups where league_id = p_league_id
      )
      select m.id,
             m.slot,
             m.franchise,
             m.division,
             count(*) filter (where s.final and s.winner = m.id)::int,
             count(*) filter (where s.final and s.winner is not null and s.winner <> m.id)::int,
             count(*) filter (where s.final and s.is_tie)::int,
             count(*) filter (where s.final and s.divisional and s.winner = m.id)::int,
             count(*) filter (where s.final and s.divisional and s.winner is not null and s.winner <> m.id)::int,
             coalesce(sum(s.pf) filter (where s.final), 0),
             coalesce(sum(s.pa) filter (where s.final), 0)
        from managers m
        left join sides s on s.manager_id = m.id
       where m.league_id = p_league_id
       group by m.id, m.slot, m.franchise, m.division
       order by m.division, 5 desc, 10 desc;
    $$;


    /**
     * A franchise added by a resize has no division, which would leave it out of
     * the divisional rematches. New slots join the smaller division, so the two
     * stay as even as the league allows.
     */
    create or replace function assign_missing_divisions(p_league_id uuid)
    returns void
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_id    uuid;
      v_divs  text[];
      v_small text;
    begin
      select array_agg(distinct division order by division) into v_divs
        from managers where league_id = p_league_id and division is not null;

      -- A league with no divisions at all splits evenly by slot.
      if v_divs is null or array_length(v_divs, 1) < 2 then
        update managers m
           set division = case when seq.rn * 2 <= seq.total then 'East' else 'West' end
          from (
            select id,
                   row_number() over (order by slot) as rn,
                   count(*) over () as total
              from managers where league_id = p_league_id
          ) seq
         where seq.id = m.id;
        return;
      end if;

      for v_id in
        select id from managers
         where league_id = p_league_id and division is null
         order by slot
      loop
        select division into v_small
          from managers
         where league_id = p_league_id and division is not null
         group by division
         order by count(*), division
         limit 1;

        update managers set division = v_small where id = v_id;
      end loop;
    end;
    $$;

    revoke all on function assign_missing_divisions(uuid) from public;

    -- Any franchise created later — by a resize, or by the seed script — joins a
    -- division automatically, so a league can never end up with a franchise that
    -- sits outside the divisional rematches.
    create or replace function assign_division_on_insert()
    returns trigger
    language plpgsql
    as $$
    declare
      v_divs  text[];
      v_small text;
    begin
      if new.division is not null then return new; end if;

      select array_agg(distinct division order by division) into v_divs
        from managers where league_id = new.league_id and division is not null;

      -- A league that has not got two divisions yet is filling the first ones, so
      -- both names have to be candidates: picking the smallest of what exists
      -- would put everybody in whichever division was created first.
      if v_divs is null or array_length(v_divs, 1) < 2 then
        v_divs := array['East', 'West'];
      end if;

      select d into v_small
        from unnest(v_divs) as d
        left join managers m
          on m.league_id = new.league_id and m.division = d
       group by d
       order by count(m.id), d
       limit 1;

      new.division := coalesce(v_small, 'East');
      return new;
    end;
    $$;

    drop trigger if exists managers_division on managers;
    create trigger managers_division
      before insert on managers
      for each row execute function assign_division_on_insert();

    insert into schema_migrations (name) values ('0009_divisions.sql');
    raise notice 'applied %', '0009_divisions.sql';
  end if;
end
$__migration__$;


-- ======================================================================
-- 0010_column_privileges.sql
-- ======================================================================

do $__migration__$
begin
  if exists (select 1 from schema_migrations where name = '0010_column_privileges.sql') then
    raise notice 'skipping %, already applied', '0010_column_privileges.sql';
  else
    -- Closing three privilege escalations.
    --
    -- Row-level security says which ROWS you may touch. It says nothing about
    -- which COLUMNS. Every policy here was correct about the row and silent about
    -- the rest, which left a signed-in manager able to rewrite fields the app
    -- never exposes — straight from a browser console with the anon key, since
    -- that is all a Supabase client needs.
    --
    --   1. managers      — set is_commissioner on your own row and you are the
    --                      commissioner. Also waiver_priority, and pin_hash.
    --   2. roster_slots  — rewrite player_name on a row you own and you have
    --                      signed any free agent, no waiver claim needed.
    --   3. trades        — set both acceptance flags on a trade you are party to
    --                      and execute_trade() will move the players, though the
    --                      other manager never agreed.
    --
    -- The fix for the first two is column-level grants: Postgres can restrict
    -- UPDATE to named columns, which is exactly the missing half. The third needs
    -- to compare old and new, so it is a trigger.

    -- --------------------------------------------------------------- managers ---
    -- A manager owns their display name and their franchise name. Everything else
    -- about them — who is commissioner, waiver order, the PIN hash, which auth
    -- user they are — is set by the signup route or a commissioner function, both
    -- of which hold the service key and are unaffected by these grants.

    revoke update on managers from authenticated, anon;
    grant update (name, franchise) on managers to authenticated;

    -- ----------------------------------------------------------- roster_slots ---
    -- A manager sets who starts. Which players are on the roster is decided by the
    -- draft, a trade or a waiver claim — never by editing the row.

    revoke update on roster_slots from authenticated, anon;
    grant update (lineup_slot) on roster_slots to authenticated;

    -- ----------------------------------------------------------------- trades ---
    /**
     * Nobody accepts on somebody else's behalf.
     *
     * Both managers in a trade can update the row — that is how countering and
     * accepting work — so the row policy cannot tell a legitimate acceptance from
     * forging the other side's. Comparing old to new can.
     *
     * The guard keys on the ROLE, not on auth.uid(). A SECURITY DEFINER function
     * runs as its owner while auth.uid() still reports the caller, so keying on
     * the identity would fire inside execute_trade() and block the very update it
     * exists to make. current_user cannot be changed by a client.
     */
    -- Deliberately NOT security definer: a definer function would run as its own
    -- owner, so current_user inside it would never be the caller's role and the
    -- check below could never fire. As an invoker trigger it runs as whoever is
    -- updating, which is the whole point.
    create or replace function guard_trade_acceptance()
    returns trigger
    language plpgsql
    set search_path = public
    as $$
    declare
      v_me uuid;
    begin
      -- Anything not arriving as a browser session — the service key, or a
      -- definer function such as execute_trade — is past this.
      if current_user not in ('authenticated', 'anon') then return new; end if;

      select id into v_me from managers where auth_user_id = auth.uid();
      if v_me is null then return new; end if;

      if v_me = new.from_manager and new.to_accepted is distinct from old.to_accepted then
        raise exception 'You cannot accept on the other manager''s behalf'
          using errcode = '42501';
      end if;

      if v_me = new.to_manager and new.from_accepted is distinct from old.from_accepted then
        raise exception 'You cannot accept on the other manager''s behalf'
          using errcode = '42501';
      end if;

      -- Only execute_trade() marks a trade executed, and it checks both
      -- acceptances first. Letting a party set it directly would either fake a
      -- completed deal or block a real one from ever running.
      if new.status = 'executed' and old.status is distinct from 'executed' then
        raise exception 'A trade is executed by accepting it, not by setting its status'
          using errcode = '42501';
      end if;

      return new;
    end;
    $$;

    drop trigger if exists trades_guard_acceptance on trades;
    create trigger trades_guard_acceptance
      before update on trades
      for each row execute function guard_trade_acceptance();

    -- execute_trade() runs as its definer and sets the status itself, so it must
    -- not trip the guard above. It is the only path that may.
    create or replace function execute_trade(p_trade_id uuid)
    returns jsonb
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_trade   trades;
      v_give    text[];
      v_get     text[];
      v_player  text;
    begin
      select * into v_trade from trades where id = p_trade_id for update;
      if v_trade.id is null then
        raise exception 'No such trade' using errcode = 'P0002';
      end if;

      if v_trade.status = 'executed' then
        raise exception 'This trade has already been executed' using errcode = '55000';
      end if;

      if not (v_trade.from_accepted and v_trade.to_accepted) then
        raise exception 'Both managers must accept first' using errcode = '55000';
      end if;

      v_give := array(select jsonb_array_elements_text(v_trade.offer -> 'give'));
      v_get  := array(select jsonb_array_elements_text(v_trade.offer -> 'get'));

      -- Every player must still be where the offer says, or nothing moves.
      foreach v_player in array v_give loop
        if not exists (
          select 1 from roster_slots
           where league_id = v_trade.league_id
             and manager_id = v_trade.from_manager
             and player_name = v_player
        ) then
          raise exception 'A player in this offer is no longer on the proposing roster'
            using errcode = '55000';
        end if;
      end loop;

      foreach v_player in array v_get loop
        if not exists (
          select 1 from roster_slots
           where league_id = v_trade.league_id
             and manager_id = v_trade.to_manager
             and player_name = v_player
        ) then
          raise exception 'A player in this offer is no longer on the receiving roster'
            using errcode = '55000';
        end if;
      end loop;

      update roster_slots
         set manager_id = v_trade.to_manager, acquired = 'trade', lineup_slot = 'BENCH'
       where league_id = v_trade.league_id
         and manager_id = v_trade.from_manager
         and player_name = any (v_give);

      update roster_slots
         set manager_id = v_trade.from_manager, acquired = 'trade', lineup_slot = 'BENCH'
       where league_id = v_trade.league_id
         and manager_id = v_trade.to_manager
         and player_name = any (v_get);

      -- The guard lets this through: this runs as the function owner, not as the
      -- authenticated role.
      update trades
         set status = 'executed', executed_at = now()
       where id = p_trade_id;

      delete from trade_block
       where league_id = v_trade.league_id
         and player_name = any (v_give || v_get);

      return jsonb_build_object(
        'ok', true, 'trade_id', p_trade_id, 'give', v_give, 'get', v_get
      );
    end;
    $$;

    revoke all on function execute_trade(uuid) from public;
    grant execute on function execute_trade(uuid) to authenticated;

    insert into schema_migrations (name) values ('0010_column_privileges.sql');
    raise notice 'applied %', '0010_column_privileges.sql';
  end if;
end
$__migration__$;


-- ======================================================================
-- 0011_commissioner_lock.sql
-- ======================================================================

do $__migration__$
begin
  if exists (select 1 from schema_migrations where name = '0011_commissioner_lock.sql') then
    raise notice 'skipping %, already applied', '0011_commissioner_lock.sql';
  else
    -- The league office belongs to one franchise, and to no other.
    --
    -- leagues.commissioner_slot already records which franchise that is — the seed
    -- writes it, and it defaults to STL. But nothing enforced it: is_commissioner
    -- was an ordinary boolean that happened to be set correctly once. Migration
    -- 0010 stopped a manager writing it from a browser, which closed the way in,
    -- but left the rule itself unstated.
    --
    -- Here it becomes an invariant. is_commissioner is not a field anyone sets; it
    -- is derived from the franchise the league names, on every insert and update,
    -- by whoever is asking — a browser session, the service key, a future
    -- migration written carelessly. There is no path that can put the office
    -- somewhere else.

    /**
     * Forces is_commissioner to match the league's commissioner_slot.
     *
     * It overwrites rather than refuses on purpose: a refusal would make ordinary
     * writes fail for reasons the caller did not intend and probably cannot see —
     * renaming a franchise should not error because the row also carried a stale
     * flag. Overwriting means the invariant simply always holds.
     */
    create or replace function enforce_commissioner_slot()
    returns trigger
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_slot text;
    begin
      select commissioner_slot into v_slot from leagues where id = new.league_id;

      -- A league that names nobody keeps whatever it has, so an existing league
      -- is not stripped of its commissioner by a null.
      if v_slot is null then return new; end if;

      new.is_commissioner := (new.slot = v_slot);
      return new;
    end;
    $$;

    drop trigger if exists managers_commissioner_slot on managers;
    create trigger managers_commissioner_slot
      before insert or update on managers
      for each row execute function enforce_commissioner_slot();

    -- Bring any league already in flight into line with its own record.
    update managers m
       set is_commissioner = (m.slot = l.commissioner_slot)
      from leagues l
     where l.id = m.league_id
       and l.commissioner_slot is not null
       and m.is_commissioner is distinct from (m.slot = l.commissioner_slot);

    -- --------------------------------------------------------------- leagues ---
    -- Moving the office means changing commissioner_slot, so that column must not
    -- be writable from a browser either — otherwise the commissioner could hand
    -- the league to themselves by another name, and the trigger above would
    -- faithfully follow.
    --
    -- The two columns the app does write through a manager's own session are the
    -- settings blob and the draft date. Everything else on the league row goes
    -- through a security-definer function that checks who is asking.

    revoke update on leagues from authenticated, anon;
    grant update (settings, draft_at) on leagues to authenticated;

    -- Changing who holds the office is deliberate, and done with the service key:
    --
    --   update leagues set commissioner_slot = 'BLZ';
    --
    -- The trigger moves is_commissioner to match on the next write to each
    -- manager, so run this afterwards to apply it at once:
    --
    --   update managers m set is_commissioner = (m.slot = l.commissioner_slot)
    --     from leagues l where l.id = m.league_id;

    insert into schema_migrations (name) values ('0011_commissioner_lock.sql');
    raise notice 'applied %', '0011_commissioner_lock.sql';
  end if;
end
$__migration__$;


-- ======================================================================
-- 0012_resize_rebuilds_schedule.sql
-- ======================================================================

do $__migration__$
begin
  if exists (select 1 from schema_migrations where name = '0012_resize_rebuilds_schedule.sql') then
    raise notice 'skipping %, already applied', '0012_resize_rebuilds_schedule.sql';
  else
    -- Resizing a league must rebuild its schedule, not just its draft board.
    --
    -- set_team_count() rebuilt the board and stopped there. The schedule was left
    -- as it was, and the franchises that went took their fixtures with them by
    -- cascade — so a league resized from twelve to ten kept a twelve-team season:
    -- sixteen weeks instead of fourteen, four games in most weeks instead of five,
    -- and two franchises idle each week for no reason anyone could see.
    --
    -- The board and the season are both derived from the league. Changing the
    -- league has to regenerate both, or one of them is quietly lying.
    --
    -- Divisions had the same shape of problem: franchises were only ever assigned
    -- when they had none, never rebalanced. Removing two from one side left six
    -- against four, and since a six-team division needs five rematch rounds while
    -- a four-team one needs three, the small division sat out entirely for two
    -- weeks of every season.

    /**
     * Evens the divisions up, moving as few franchises as possible.
     *
     * Deliberate assignments are worth keeping, so this does not reshuffle: it
     * moves the fewest franchises from the larger division to the smaller, newest
     * slot first, and stops as soon as they are within one of each other.
     */
    create or replace function rebalance_divisions(p_league_id uuid)
    returns int
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_big    text;
      v_small  text;
      v_n_big  int;
      v_n_small int;
      v_moved  int := 0;
      v_id     uuid;
    begin
      loop
        select division, n into v_big, v_n_big
          from (select division, count(*) n from managers
                 where league_id = p_league_id and division is not null
                 group by division) d
         order by n desc, division limit 1;

        select division, n into v_small, v_n_small
          from (select division, count(*) n from managers
                 where league_id = p_league_id and division is not null
                 group by division) d
         order by n, division limit 1;

        exit when v_big is null or v_small is null or v_big = v_small;
        exit when v_n_big - v_n_small <= 1;

        select id into v_id
          from managers
         where league_id = p_league_id and division = v_big
         order by slot desc
         limit 1;

        exit when v_id is null;

        update managers set division = v_small where id = v_id;
        v_moved := v_moved + 1;

        -- Bounded: every pass moves one franchise across, so the gap always
        -- shrinks. The guard is only here so a surprise cannot spin forever.
        exit when v_moved > 32;
      end loop;

      return v_moved;
    end;
    $$;

    revoke all on function rebalance_divisions(uuid) from public;

    create or replace function set_team_count(p_league_id uuid, p_count int)
    returns jsonb
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_me       managers;
      v_current  int;
      v_blocked  text[];
      v_removing uuid[];
      v_slot     text;
      v_i        int;
      v_made     int;
      v_sched    jsonb;
    begin
      select * into v_me from managers where auth_user_id = auth.uid();
      if v_me.id is null or not v_me.is_commissioner or v_me.league_id <> p_league_id then
        raise exception 'Only the commissioner can change the league size'
          using errcode = '42501';
      end if;

      if p_count < 2 or p_count > 16 then
        raise exception 'A league runs from 2 to 16 franchises' using errcode = '22003';
      end if;

      select count(*) into v_made
        from draft_picks
       where league_id = p_league_id and player_name is not null;

      if v_made > 0 then
        raise exception 'The draft has already started — the league size is fixed now'
          using errcode = '55000';
      end if;

      -- A played week fixes the league's shape just as firmly as a made pick:
      -- generate_schedule would refuse below anyway, but failing here says why.
      if exists (select 1 from matchups where league_id = p_league_id and final) then
        raise exception 'Weeks have already been played — the league size is fixed now'
          using errcode = '55000';
      end if;

      select count(*) into v_current from managers where league_id = p_league_id;

      if p_count < v_current then
        -- Removal runs from the end of the alphabet, and the commissioner's slot
        -- has no reason to be safe there — STL sorts near the back. Deleting the
        -- office holder would leave a league nobody can administer, so the
        -- commissioner is never a candidate.
        select array_agg(id order by slot desc)
          into v_removing
          from (
            select id, slot from managers
             where league_id = p_league_id
               and not is_commissioner
             order by slot desc
             limit (v_current - p_count)
          ) doomed;

        if coalesce(array_length(v_removing, 1), 0) < v_current - p_count then
          raise exception
            'Cannot shrink to % — only the commissioner''s franchise would be left to remove',
            p_count using errcode = '55000';
        end if;

        select array_agg(distinct m.franchise)
          into v_blocked
          from managers m
         where m.id = any (v_removing)
           and (
             m.pin_hash is not null
             or exists (select 1 from roster_slots r where r.manager_id = m.id)
           );

        if v_blocked is not null then
          raise exception 'These franchises are claimed or hold players: %',
            array_to_string(v_blocked, ', ')
            using errcode = '55000';
        end if;

        delete from managers where id = any (v_removing);

      elsif p_count > v_current then
        for v_i in (v_current + 1)..p_count loop
          v_slot := 'T' || lpad(v_i::text, 2, '0');
          while exists (select 1 from managers where league_id = p_league_id and slot = v_slot) loop
            v_slot := v_slot || 'X';
          end loop;

          insert into managers (league_id, slot, name, franchise, pin_hash, is_commissioner)
          values (p_league_id, v_slot, 'Open', 'Franchise ' || v_i, null, false);
        end loop;
      end if;

      perform assign_missing_divisions(p_league_id);
      -- Without this a resize leaves the divisions lopsided, and the smaller one
      -- sits out whole weeks of the rematch phase.
      perform rebalance_divisions(p_league_id);
      perform rebuild_draft_board(p_league_id);

      -- The season is derived from the league too. Without this the old schedule
      -- survives with holes in it where the departed franchises used to be.
      v_sched := generate_schedule(p_league_id);

      insert into admin_log (league_id, actor, action, detail)
      values (p_league_id, v_me.id, 'team_count_changed',
              jsonb_build_object('from', v_current, 'to', p_count,
                                 'weeks', v_sched -> 'weeks'));

      return jsonb_build_object(
        'ok', true,
        'teams', p_count,
        'was', v_current,
        'weeks', v_sched -> 'weeks',
        'matchups', v_sched -> 'matchups'
      );
    end;
    $$;

    revoke all on function set_team_count(uuid, int) from public;
    grant execute on function set_team_count(uuid, int) to authenticated;

    /**
     * Rebuilds a league's season if the one it has does not match the league.
     *
     * Returns true if it rebuilt. The test is the only honest one available:
     * work out how many games the current roster implies for each franchise —
     * everyone once, then divisional rivals a second time — and see whether the
     * fixtures on record agree. A schedule left over from a larger league shows
     * up as franchises short of their games, which is exactly the hole a resize
     * used to leave behind.
     *
     * Counting idle weeks would not do: a division with an odd number of
     * franchises leaves somebody out every rematch week quite legitimately, and
     * flagging that would reshuffle healthy leagues every time this ran.
     */
    create or replace function repair_schedule(p_league_id uuid)
    returns boolean
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_n  int;
      v_ok boolean;
    begin
      -- A season under way is never touched, whatever shape it is in.
      if exists (select 1 from matchups where league_id = p_league_id and final) then
        return false;
      end if;

      -- Nothing to repair until a schedule exists.
      if not exists (select 1 from matchups where league_id = p_league_id) then
        return false;
      end if;

      perform rebalance_divisions(p_league_id);

      select count(*) into v_n from managers where league_id = p_league_id;
      if v_n < 2 then return false; end if;

      select bool_and(
               played = v_n - 1 + case when m.division is null then 0 else sizes.d - 1 end
             )
        into v_ok
        from managers m
        join (
          select division, count(*) d from managers
           where league_id = p_league_id group by division
        ) sizes on sizes.division is not distinct from m.division
        cross join lateral (
          select count(*) as played from matchups x
           where x.league_id = p_league_id
             and (x.home_manager = m.id or x.away_manager = m.id)
        ) mine
       where m.league_id = p_league_id;

      if coalesce(v_ok, false) then return false; end if;

      perform generate_schedule(p_league_id);
      return true;
    end;
    $$;

    revoke all on function repair_schedule(uuid) from public;

    -- Repair any league already carrying a schedule from a size it no longer is.
    do $repair$
    declare
      v_league uuid;
    begin
      for v_league in select id from leagues loop
        if repair_schedule(v_league) then
          raise notice 'rebuilt the schedule for league %', v_league;
        end if;
      end loop;
    end
    $repair$;

    insert into schema_migrations (name) values ('0012_resize_rebuilds_schedule.sql');
    raise notice 'applied %', '0012_resize_rebuilds_schedule.sql';
  end if;
end
$__migration__$;


-- ======================================================================
-- 0013_reset_draft.sql
-- ======================================================================

do $__migration__$
begin
  if exists (select 1 from schema_migrations where name = '0013_reset_draft.sql') then
    raise notice 'skipping %, already applied', '0013_reset_draft.sql';
  else
    -- Resetting the draft: putting the league back to the morning of draft day.
    --
    -- A draft can go wrong in ways no rule catches. The board was built before two
    -- franchises were added, somebody was autodrafted through a whole round while
    -- their power was out, half the room turned up an hour late. The commissioner
    -- needs a way to say "none of that happened" without a database console.
    --
    -- It undoes the draft, not the season. Once a week has been graded the rosters
    -- are part of the record — those players scored those points — so a reset is
    -- refused from that moment on.

    /**
     * Puts the league back to before the draft: no rosters, a fresh board, the
     * room closed.
     *
     * Every roster goes, not only the players taken in the draft. A player who was
     * drafted and later traded is carried as a trade, and one picked up off waivers
     * was never drafted at all — leaving either behind would reopen the board with
     * players already owned, and the room would offer them to somebody else.
     *
     * The board is rebuilt rather than blanked, so it reflects the league as it
     * stands now: a franchise count or a lottery order that changed since the last
     * board was drawn is picked up here.
     *
     * Draft queues are left alone. They are a manager's own preparation, and
     * players taken in the draft were removed from every queue as they went — that
     * ordering cannot be recovered, but wiping what remains would destroy work
     * nobody asked to lose.
     */
    create or replace function reset_draft(p_league_id uuid)
    returns jsonb
    language plpgsql
    security definer
    set search_path = public
    as $$
    declare
      v_me       managers;
      v_picks    int;
      v_rostered int;
      v_claims   int;
      v_trades   int;
    begin
      select * into v_me from managers where auth_user_id = auth.uid();
      if v_me.id is null or not v_me.is_commissioner or v_me.league_id <> p_league_id then
        raise exception 'Only the commissioner can reset the draft' using errcode = '42501';
      end if;

      -- A graded week is history. Undoing the draft under it would leave scores
      -- that no roster in the league can account for.
      if exists (select 1 from matchups where league_id = p_league_id and final) then
        raise exception 'Weeks have already been played — the draft cannot be reset now'
          using errcode = '55000';
      end if;

      select count(*) into v_picks
        from draft_picks where league_id = p_league_id and player_name is not null;

      select count(*) into v_rostered
        from roster_slots where league_id = p_league_id;

      delete from roster_slots where league_id = p_league_id;

      -- An offer names players on rosters that no longer exist. execute_trade
      -- would refuse it, but leaving offers standing that can never go through is
      -- its own confusion, so they are declined here where the reason is plain.
      update trades
         set status = 'declined'
       where league_id = p_league_id
         and status in ('open', 'countered', 'agreed');
      get diagnostics v_trades = row_count;

      -- Same for claims: everyone named is a free agent again, and the drop they
      -- were paired with is gone. Settling them as cancelled leaves the reason on
      -- the record rather than deleting a manager's work without explanation.
      update waiver_claims
         set status = 'cancelled',
             reason = 'The draft was reset',
             settled_at = now()
       where league_id = p_league_id and status = 'pending';
      get diagnostics v_claims = row_count;

      -- Nobody owns anybody, so nobody has anybody to shop.
      delete from trade_block where league_id = p_league_id;

      -- rebuild_draft_board refuses while picks are made, which is the point of
      -- that guard everywhere else. Here the picks are being deliberately undone,
      -- so they go first.
      delete from draft_picks where league_id = p_league_id;
      perform rebuild_draft_board(p_league_id);

      update leagues
         set draft_state = 'pending',
